INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1193, 'koKR', 'Zepsuta pułapka', '', '', '', 'Wróć do Zepsutej pułapki w Górach Alterak.', '', '', '', '', 0),
(1318, 'koKR', 'Niedokończone sprawy Gordoków', 'Teraz ty król, to może ty odzyskać cenny artefakt Gordoków od dziwacznego elfa, co sam siebie nazywa księciem! Król przed tobą nie dać rady, tak samo jak wszyscy inni królowie, odkąd Tortheldrin – ten dziwaczny elf – ukraść go dawnemu królowi Gordoków!$B$BArtefakt nazywa się Rękawica pancerna potęgi Gordoków. Dawne opowieści mówić, że tylko jeden prawdziwy król Gordoków może go odzyskać. Dawna opowieść mówić też, że dziwaczny elf dalej tu gdzieś jest – ty go znaleźć, a on się stać potężną rękawicą, co ty nosić na zawsze! Tak, ja ci pokazać!', 'Znajdź Rękawicę pancerną potęgi Gordoków i przynieś ją kapitanowi Kromcrushowi w Srogomłotach.$B$BWedług Kromcrusha „dawna opowieść” mówi, że Tortheldrin – „dziwaczny” elf, który nazywał siebie księciem – ukradł ją jednemu z królów Gordoków.', '', 'Wróć do kapitana Kromcrusha na Wyspie Fenris w Srebrzystym Borze.', '', '', '', '', 0),
(5518, 'koKR', 'Strój ogra Gordoków', 'Jeśli zamierzasz walczyć z królem tej nory – a chyba właśnie to cię czeka – musisz się jakoś przedostać obok kapitana Kromcrusha. Jasne, możesz go po prostu zabić. Ale może $gwolałbyś:wolałabyś; go zostawić przy życiu.$B$BJak, pytasz? Odkąd tu siedzę, chyba wymyśliłem, jak zrobić strój ogra, który wytrzyma dość długo, żeby oszukać te matoły. Jedyny problem to trwałość – najwyżej dziesięć minut. Przynieś mi, czego potrzebuję, a zrobię ci taki. I tak nigdzie się nie wybieram...', 'Przynieś 4 bele runicznej tkaniny, 8 kawałków chropowatej skóry, 2 runiczne nici i ogrzy garbnik Knotowi Naparstkowi. Jest przykuty łańcuchem w skrzydle Gordoków w Srogomłotach.', '', 'Wróć do Knota Naparstka nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(5519, 'koKR', 'Strój ogra Gordoków', '', '', '', 'Wróć do Knota Naparstka w Górach Alterak.', '', '', '', '', 0),
(5525, 'koKR', 'Uwolnić Knota!', '', '', '', 'Wróć do Knota Naparstka w Górach Alterak.', '', '', '', '', 0),
(5528, 'koKR', 'Degustacja u Gordoków', '', '', '', '', '', '', '', '', 0),
(7429, 'koKR', 'Uwolnić Knota!', '', '', '', 'Wróć do Knota Naparstka w Górach Alterak.', '', '', '', '', 0),
(7461, 'koKR', 'Szaleństwo w murach', 'Czy $gusłyszałeś:usłyszałaś; już dość? Czy jesteś $gczłowiekiem:kobietą; czynu?$B$BTo szaleństwo musi się skończyć. Era nieśmiertelnych dawno minęła. Zniszcz strażników otaczających pylony, by opuścić pole siłowe. Gdy to zrobisz, zniszcz Immol\'thara. Gdy moc księcia znacznie osłabnie, zaatakuj go i połóż mu kres. Pozwól duchom tego miasta spocząć w pokoju, $gposzukiwaczu:poszukiwaczko; przygód.', 'Musisz zniszczyć strażników otaczających 5 pylonów zasilających Więzienie Immol\'thara. Gdy pylony przestaną działać, pole siłowe otaczające Immol\'thara zniknie.$B$BWejdź do Więzienia Immol\'thara i zgładź plugawego demona, który tkwi w jego sercu. Na koniec stań do walki z księciem Tortheldrinem w Atenaeum.$B$BGdy wykonasz to zadanie, wróć do Pradawnej Shen\'dralar na dziedzińcu.', '', 'Wróć do Pradawnej Shen\'dralar w Srogomłotach.', '', '', '', '', 0),
(7462, 'koKR', 'Skarb Shen\'dralar', 'W bibliotece, w Atenaeum, znajdziesz starożytną skrzynię ukrytą pod schodami. Weź z niej to, czego pragniesz.', 'Wróć do Atenaeum i znajdź Skarb Shen\'dralar. Odbierz swoją nagrodę!', '', '', '', '', '', '', 0),
(7463, 'koKR', 'Tajemny poczęstunek', 'Mag z twojej rasy! Cudownie. Nie widziałem nikogo z twojego rodu od... och, ile to już? Od 500 lat!$B$BMam coś, co ugasi twoje pragnienie, ale najpierw musisz wykonać dla mnie zadanie.$B$B<Lydros chichocze.>$B$BW Eldre\'Thalas pojawiła się anomalia. Wodny żywiołak zadomowił się we wschodnim skrzydle. Jego obecność trzeba skatalogować!$B$BUdaj się do Dzielnicy Wypaczonego Drzewa i pobierz porcję żywiołaczej esencji Hydromiotu. Przynieś mi ją, a nauczę cię przydatnej sztuczki.', 'Udaj się do Dzielnicy Wypaczonego Drzewa w Srogomłotach i zabij wodnego żywiołaka zwanego Hydromiotem. Wróć z Esencją Hydromiotu do Wiedzącego Lydrosa w Atenaeum.', '', 'Wróć do Wiedzącego Lydrosa w Dalarańskim Kraterze w Górach Alterak.', '', '', '', '', 0),
(7483, 'koKR', 'Libram szybkości', 'Mistrz Winthalus zgubił Libram szybkości we wschodnim skrzydle. Libram pozwala nałożyć na ekwipunek drobną sztuczkę przyspieszenia. Jarmarczne sztuczki, doprawdy...$B$BTak czy inaczej, jeśli cię to interesuje, musisz przynieść Libram razem z kilkoma podstawowymi odczynnikami.$B$BHmm... Zdaje się, że potrzeba też krwi bohaterów, nieskazitelnego czarnego diamentu i dużych lśniących odłamków. Mogę się mylić!$B$B<Lydros wzrusza ramionami.>', 'Przynieś Libram szybkości, 1 nieskazitelny czarny diament, 2 duże lśniące odłamki i 2 porcje krwi bohaterów Wiedzącemu Lydrosowi w Srogomłotach, by otrzymać Arkanum szybkości.', '', 'Wróć do Wiedzącego Lydrosa w Dalarańskim Kraterze w Górach Alterak.', '', '', '', '', 0),
(7484, 'koKR', 'Libram skupienia', 'Ten libram niemal wzbudził zainteresowanie chowańca jednego z młodszych Wiedzących. Biedactwo, miało zaledwie kilka tygodni.$B$BCi z was, którzy mają większe skłonności magiczne, mogą uznać ten przedmiot za interesujący.$B$BLibram skupienia zaginął w tym skrzydle. Mogę tylko przypuszczać, że ma go któryś z duchów Wysoko Urodzonych.$B$BPrzynieś Libram razem z dużymi lśniącymi odłamkami, skórą cienia i nieskazitelnym czarnym diamentem, a wyczaruję Arkanum.', 'Przynieś Libram skupienia, 1 nieskazitelny czarny diament, 4 duże lśniące odłamki i 2 skóry cienia Wiedzącemu Lydrosowi w Srogomłotach, by otrzymać Arkanum skupienia.', '', 'Wróć do Wiedzącego Lydrosa w Dalarańskim Kraterze w Górach Alterak.', '', '', '', '', 0),
(7485, 'koKR', 'Libram ochrony', 'Płakał jak niemowlę po stracie tego libramu. Przyznaję, sam płakałem nad tekstami – nie ma większej straty niż utrata wiedzy i historii – ale płakać nad tą niemal bezużyteczną mieszaniną inkantacji? Niedorzeczne! Doszedłem do wniosku, że książę wyświadczył mu przysługę, obdzierając jego kości z ciała.$B$BPrzynieś Libram razem z nieskazitelnym czarnym diamentem, dużymi lśniącymi odłamkami i postrzępionym szwem plugastwa, a odtworzę Arkanum.$B$BA, i sprawdź północne skrzydło.', 'Przynieś Libram ochrony, 1 nieskazitelny czarny diament, 2 duże lśniące odłamki i 1 postrzępiony szew plugastwa Wiedzącemu Lydrosowi w Srogomłotach, by otrzymać Arkanum ochrony.', '', 'Wróć do Wiedzącego Lydrosa w Dalarańskim Kraterze w Górach Alterak.', '', '', '', '', 0),
(7498, 'koKR', 'Garona: studium skrytości i zdrady', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7499, 'koKR', 'Kodeks obrony', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7500, 'koKR', 'Książka kucharska arkanisty', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7501, 'koKR', 'Światłość i jak nią wywijać', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7502, 'koKR', 'Okiełznanie cieni', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7503, 'koKR', 'Najwspanialsza rasa łowców', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7504, 'koKR', 'Święte bzdury: czego Światłość ci nie powie', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7505, 'koKR', 'Wstrząs mrozu i ty', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7506, 'koKR', 'Szmaragdowy Sen...', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7507, 'koKR', 'Kompendium Forora', '$GOdkryłeś:Odkryłaś; coś niezwykle ważnego. Ta księga nie przypomina żadnej, którą dotąd $gwidziałeś:widziałaś;.$B$BWygląda na to, że ktoś lub coś zdołało złamać pieczęć Atenaeum. Tekst w środku jest pomieszany i ledwie czytelny.', 'Zwróć Kompendium Forora o zabijaniu smoków do Atenaeum.', '', '', '', '', '', '', 0),
(7508, 'koKR', 'Wykuwanie Quel\'Serrar', 'Jeśli chcesz się podjąć tego zadania, pokaż Lydrosowi tępe ostrze.', 'Daj Tępe i płaskie elfie ostrze Wiedzącemu Lydrosowi.', '', '', '', '', '', '', 0),
(7649, 'koKR', 'Zaklęta zbroja płytowa z torium: tom I', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7650, 'koKR', 'Zaklęta zbroja płytowa z torium: tom II', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7651, 'koKR', 'Zaklęta zbroja płytowa z torium: tom III', 'Księga nosi znak Atenaeum.', 'Zwróć księgę prawowitym właścicielom.', '', '', '', '', '', '', 0),
(7703, 'koKR', 'Niedokończone sprawy Gordoków', 'Teraz ty król, to może ty odzyskać cenny artefakt Gordoków od dziwacznego elfa, co sam siebie nazywa księciem! Król przed tobą nie dać rady, tak samo jak wszyscy inni królowie, odkąd Tortheldrin – ten dziwaczny elf – ukraść go dawnemu królowi Gordoków!$B$BArtefakt nazywa się Rękawica pancerna potęgi Gordoków. Dawne opowieści mówić, że tylko jeden prawdziwy król Gordoków może go odzyskać. Dawna opowieść mówić też, że dziwaczny elf dalej tu gdzieś jest – ty go znaleźć, a on się stać potężną rękawicą, co ty nosić na zawsze! Tak, ja ci pokazać!', 'Znajdź Rękawicę pancerną potęgi Gordoków i przynieś ją kapitanowi Kromcrushowi w Srogomłotach.$B$BWedług Kromcrusha „dawna opowieść” mówi, że Tortheldrin – „dziwaczny” elf, który nazywał siebie księciem – ukradł ją jednemu z królów Gordoków.', '', 'Wróć do kapitana Kromcrusha na Wyspie Fenris w Srebrzystym Borze.', '', '', '', '', 0),
(7877, 'koKR', 'Skarb Shen\'dralar', 'W bibliotece, w Atenaeum, znajdziesz starożytną skrzynię ukrytą pod schodami. Weź z niej to, czego pragniesz.', 'Wróć do Atenaeum i znajdź Skarb Shen\'dralar. Odbierz swoją nagrodę!', '', '', '', '', '', '', 0),
(8949, 'koKR', 'Wendeta Falrina', 'Tak, to prawda, że znam zaklęcie, którego potrzebujesz. Nie mam jednak w zwyczaju wyświadczać przysług za darmo, nawet jeśli przysłał cię tu stary przyjaciel.$B$BŻywię wyłącznie nienawiść i pogardę dla naszych prymitywnych ogrzych sąsiadów. I nie tylko dla nich – nienawidzę zwolenników Omokka tak samo jak tych, którzy idą za królem Gordokiem.$B$BChcę, żebyś ich $gzabijał:zabijała;. Zabij ich mnóstwo! Przynieś mi paciorki, które noszą na szyjach, jako dowód swojej pracy. Zrób to, a porozmawiamy o twojej prośbie.', 'Zbierz 25 ogrzych paciorków wojennych od ogrów w Srogomłotach lub w Iglicy Czarnej Góry i wróć do Falrina Kształtującego Drzewa w Atenaeum w Srogomłotach.', '', 'Wróć do Falrina Kształtującego Drzewa w Dalarańskim Kraterze w Górach Alterak.', '', '', '', '', 0),
(8950, 'koKR', 'Zaklęcie prowokatora', 'Z łatwością mogę nałożyć na sztandar zaklęcie, którego potrzebujesz, $N. Niestety nie mam potrzebnych materiałów, bo bardzo rzadko ktoś prosi o tego rodzaju urok.$B$BBędę potrzebował esencji jednego z duchów z Eldreth, które nawiedzają te korytarze, garści mrocznych run ze Scholomancjum i kilku dużych lśniących odłamków. Przynieś mi te odczynniki, a wykonam dla ciebie to zadanie.', 'Przynieś Falrinowi Kształtującemu Drzewa w Srogomłotach: 1 Esencję szyderczego widma, 4 mroczne runy i 8 dużych lśniących odłamków.', '', 'Wróć do Falrina Kształtującego Drzewa w Dalarańskim Kraterze w Górach Alterak.', '', '', '', '', 0),
(9030, 'koKR', '', '', 'Porozmawiaj z Delianą w Żelaznej Kuźni.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(1193, 'koKR', 'Ustrojstwo z torium bez trudu wsuwa się na miejsce, tworząc kanał, którym można wlać olej mrozu. Gdy ostatnie krople oleju spływają do środka, pułapka zatrzaskuje się w gotowości.$B$BBiada każdemu nieostrożnemu ogrowi, który akurat będzie tędy przechodził!', 0),
(5518, 'koKR', 'Tak, to wystarczy. Tu wsunąć, tu podwinąć... he, będzie w sam raz! <Na twarzy skutego goblina pojawia się szeroki uśmiech.>$B$BProszę bardzo, wszystko gotowe. Pamiętaj – to nie jest najsolidniej uszyta rzecz na świecie. Masz dziesięć minut, zanim się rozleci, a potem już nikogo nie oszukasz! Spróbuj go włożyć tuż przed tym, jak do niego podejdziesz, i pamiętaj... on uzna za sojusznika tylko CIEBIE, a nie twoich towarzyszy!', 0),
(5519, 'koKR', 'Proszę bardzo, $N – włóż to, a przez dziesięć minut będziesz $gmógł:mogła; robić, co zechcesz. Powodzenia!$B$BA, i jeśli przypadkiem znajdziesz klucz, żeby mnie stąd wyciągnąć, KONIECZNIE DAJ MI ZNAĆ!!!', 0),
(5525, 'koKR', 'Ty – numer jeden. Cała reszta – numer dwa albo niżej. Och, dziękuję, że mnie $guwolniłeś:uwolniłaś;!$B$BWiedziałem, że jestem stworzony do czegoś więcej niż bycie przystawką dla jakiegoś ogra!', 0),
(5528, 'koKR', 'Ty teraz wielki szef, to ty dostać darmowe próbki moich lepszych trunków! Te napoje cię wzmocnić I dać dobry szmerek! To dobre trunki, wodzu... ty spróbować i sam powiedzieć Kreegowi!', 0),
(7429, 'koKR', 'Och, dziękuję, że mnie $guwolniłeś:uwolniłaś;! Ty – numer jeden. Cała reszta – numer dwa albo niżej.$b$bWiedziałem, że jestem stworzony do czegoś więcej niż bycie przystawką dla jakiegoś ogra!', 0),
(7461, 'koKR', 'Dziękujemy ci, $gbohaterze:bohaterko;.', 0),
(7462, 'koKR', 'Otwierasz skrzynię i znajdujesz...', 0),
(7463, 'koKR', 'Cudownie! Kim ty właściwie jesteś? Och, nieważne. Co ja ci miałem dać? Hmm... cóż, przy twojej profesji może ci się to przydać.', 0),
(7483, 'koKR', '<Lydros ziewa.>$B$BZgodnie z obietnicą – Arkanum szybkości. Nie wydaj wszystkiego w jednym miejscu.$B$B<Lydros chichocze.>', 0),
(7484, 'koKR', 'Tylko nie zrób sobie krzywdy, nakładając zaklęcie.', 0),
(7485, 'koKR', 'Tak, tak... Uspokój się. Zgodnie z obietnicą, oto twoje Arkanum.', 0),
(7498, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7499, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7500, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7501, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7502, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7503, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7504, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7505, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7506, 'koKR', 'Świetna robota. Jeśli znajdziesz więcej ksiąg, nie wahaj się nam ich zwrócić.$B$BZ czasem zmieniamy, a nawet dodajemy nowe nagrody za zwrot zaginionych ksiąg.', 0),
(7507, 'koKR', 'Za tę księgę $gmógłbyś:mogłabyś; dostać sporo złota na czarnym rynku, $N. Zwłaszcza że ochronna pieczęć została złamana, przez co sekrety zabijania smoków stoją otworem przed każdym, komu starczy rozumu, by przyswoić wiedzę zawartą na tych świętych stronach.$B$BByć może należy się wielka nagroda... Cóż, nagroda, której zdobycie będzie wymagać ogromnego wysiłku.$B$B<Lydros się uśmiecha.>', 0),
(7508, 'koKR', 'Jeśli zdołasz wejść do leża smoczycy, rozgrzać ostrze w jej ognistym oddechu, a w końcu zahartować je w jej krwi, zwiążę ostrze z tobą.', 0),
(7649, 'koKR', 'Dobra robota, $gmój chłopcze:moja dziewczyno;.$B$B<Wiedzący Lydros wyrywa z księgi stronę.>$B$BNa pewno zrobisz użytek z tego przepisu.', 0),
(7650, 'koKR', 'Dobra robota, $gmój chłopcze:moja dziewczyno;.$B$B<Wiedzący Lydros wyrywa z księgi stronę.>$B$BNa pewno zrobisz użytek z tego przepisu.', 0),
(7651, 'koKR', 'Dobra robota, $gmój chłopcze:moja dziewczyno;.$B$B<Wiedzący Lydros wyrywa z księgi stronę.>$B$BNa pewno zrobisz użytek z tego przepisu.', 0),
(7703, 'koKR', 'Łał... ty NAPRAWDĘ $gprawdziwy król:prawdziwa królowa;! Ja nigdy nie myśleć, że zobaczyć tę rękawicę w życiu! Ona wyglądać, jakby nie mieć już żadne mojo... może ten dziwaczny elf próbować zepsuć rękawicę. No to ja mu mówić HAR HAR!$b$bPatrz – ten znak na rękawicy to stary, stary, BARDZO stary magiczny znak, starszy niż Gordokowie, tak mówić. No i jako kapitan Gordoków my wszyscy się uczyć jedną rzecz w kółko – jak obudzić znak i oddać rękawicy moc!$b$bJa to zrobić dla ciebie, $gmój królu:moja królowo;! Masz, weź rękawicę i rządź NA ZAWSZE!', 0),
(7877, 'koKR', 'Otwierasz skrzynię i znajdujesz...', 0),
(8949, 'koKR', 'Hmmm... Dziwne, ale wcale nie czuję się lepiej z powodu śmierci brata z rąk tych prymitywów.$B$BCóż, $gdotrzymałeś:dotrzymałaś; swojej części umowy. Zobaczmy, co mogę dla ciebie zrobić.', 0),
(8950, 'koKR', 'Tak, to w zupełności wystarczy. Gdy skończę, żadna siła na świecie nie zdoła powstrzymać twojej ofiary przed przyjęciem twojego wyzwania.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(1193, 'koKR', 'Przed tobą leży wielka, zepsuta pułapka. Wygląda na to, że ogry próbowały ją naprawić, ale bez skutku. Obok leży napisany w pośpiechu liścik, który – co dziwne – dokładnie wyjaśnia, czego potrzeba do naprawy: ustrojstwa z torium i trochę oleju mrozu. Gdyby pułapkę naprawić, przechodzący obok ogr mógłby w nią wpaść i dałoby się go ominąć.$b$bNajwyraźniej to szczęśliwy traf, że tak niewiele ogrów umie czytać.$b$bNajwyraźniej.', 0),
(5518, 'koKR', 'Ogrzy garbnik to chyba najtrudniejsza do zdobycia rzecz z tych, których potrzebuję do stroju – zdaje się, że mają trochę na górze? Trudno powiedzieć, bo z tą kulą u nogi niełatwo się poruszać...$B$BW każdym razie przynieś mi, czego potrzebuję, a wyczaruję ci strój ogra, dzięki któremu kapitan Kromcrush weźmie cię za jednego ze swoich ludzi.', 0),
(5519, 'koKR', 'Potrzebujesz kolejnego stroju, co? Cóż, wygląda na to, że nigdzie się nie wybieram – przynieś mi to samo co poprzednio, a zrobię ci następny strój ogra.', 0),
(5525, 'koKR', 'Nazywa się Klucz do kajdan Gordoków – przynajmniej tak go nazywają te góry sadła. Chyba każdy ogr może go mieć, ale nie wiem, czy któryś konkretny go ma. Może strażnicy mają największe szanse...$B$BCo ja gadam – przecież już go masz, prawda?! To on??!', 0),
(7429, 'koKR', 'Nazywa się Klucz do kajdan Gordoków – przynajmniej tak go nazywają te góry sadła. Chyba każdy ogr może go mieć, ale nie wiem, czy któryś konkretny go ma. Może strażnicy mają największe szanse...$b$bCo ja gadam – przecież już go masz, prawda?! To on??!', 0),
(7461, 'koKR', 'Uważaj, $gposzukiwaczu:poszukiwaczko; przygód. Książę potrafi być... przekonujący.', 0),
(7463, 'koKR', 'Tak? Czy my się znamy?', 0),
(7483, 'koKR', 'O co chodzi? Mam mnóstwo katalogowania!', 0),
(7484, 'koKR', 'Znowu ty? Czego możesz jeszcze chcieć?', 0),
(7485, 'koKR', 'Tylko moja cierpliwość oszczędza ci cierpień.', 0),
(7498, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7499, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7500, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7501, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7502, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7503, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7504, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7505, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7506, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7507, 'koKR', 'Ach, jedno z naszych największych kompendiów. Zaginęło przed wiekami.', 0),
(7508, 'koKR', 'Doskonale, zaczynajmy...', 0),
(7649, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7650, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7651, 'koKR', '$GOdzyskałeś:Odzyskałaś; księgę!', 0),
(7703, 'koKR', 'Ha, ty jej nie znaleźć, co, szefie? Może dawna opowieść to zła opowieść... trudno uwierzyć, że dziwaczny elf móc ukraść coś królowi Gordoków!', 0),
(8949, 'koKR', 'Czy $gwyświadczyłeś:wyświadczyłaś; mi przysługę, o którą prosiłem, $N?', 0),
(8950, 'koKR', 'Czy $gzebrałeś:zebrałaś; materiały, których potrzebuję, $N?', 0);
