INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2631, 'koKR', '<Strony pokrywają starożytne elfie runy.>$B$BZawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania większego arkanum.$B$BOby nasi wrogowie nigdy nie zdobyli tych librami.$B$BObym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas.$B$BObym umarł jedynie z łaski Kael\'thasa.$B$BObym zabijał na chwałę Illidana.$B$B– Mistrz Kariel Winthalus', 0),
(2632, 'koKR', '<Nie rozumiesz niczego, co zapisano na tych stronach.> ', 0),
(2633, 'koKR', '<Strony pokrywają starożytne elfie runy.>$B$BZawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania większego arkanum.$B$BOby nasi wrogowie nigdy nie zdobyli tych librami.$B$BObym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas.$B$BObym umarł jedynie z łaski Kael\'thasa.$B$BObym zabijał na chwałę Illidana.$B$B– Mistrz Kariel Winthalus', 0),
(2634, 'koKR', '<Atrament wiruje i przesuwa się po stronie. Masz wrażenie, że księga sobie z ciebie drwi.> ', 0),
(2635, 'koKR', '<Strony pokrywają starożytne elfie runy.>$B$BZawarte tu stronice przechowują wspomnienia wydarzeń, które towarzyszyły zbieraniu i tworzeniu odczynników potrzebnych do wykonania większego arkanum.$B$BOby nasi wrogowie nigdy nie zdobyli tych librami.$B$BObym dożył dnia, gdy blade światło księżyca znów rozświetli Quel\'Thalas.$B$BObym umarł jedynie z łaski Kael\'thasa.$B$BObym zabijał na chwałę Illidana.$B$B– Mistrz Kariel Winthalus', 0),
(2636, 'koKR', '<Gdy zerkasz na te strony, czujesz palący ból.>', 0),
(2637, 'koKR', 'Kompendium Forora o zabijaniu smoków to gruba księga pełna zapisków. Niestety tekst wydaje się pomieszany i nie ma dla ciebie żadnego sensu.', 0);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(5602, 0, 'koKR', 'Dziękujemy, Żelaznokory. Możesz już otworzyć drzwi.', ''),
(5667, 2, 'koKR', 'Wiesz, $gznalazłem:znalazłam; ten klucz do kajdan...', ''),
(5667, 3, 'koKR', 'Po co mam naprawiać pułapkę? Czemu nie załatwić strażnika po staremu?', ''),
(5668, 0, 'koKR', 'Chyba tak!', ''),
(5721, 0, 'koKR', 'Jak to kupić?! Teraz ja jestem $gkrólem:królową;... a dobrze jest być $gkrólem:królową;!', ''),
(5721, 1, 'koKR', 'Pokaż, jaki bimber masz na sprzedaż, Kreeg.', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(11466, 0, 0, 'koKR', 'Demon się uwolnił! Szybko, musimy go poskromić!'),
(14324, 0, 0, 'koKR', 'Król nie żyć – O NIEEE! Wezwać Mizzle\'a Przebiegłego! On wiedzieć, co robić dalej!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(9099, 'koKR', 'Jak sobie życzysz...', '', 0),
(9100, 'koKR', 'Moja siła słabnie, śmiertelna istoto. Obietnica została dotrzymana, droga jest wolna. Teraz powracam tam, skąd pochodzę.', '', 0),
(9101, 'koKR', 'Bezradność... bezsilność... przywrócić... muszę przywrócić... Zevrim panuje... skończ tę mękę...', '', 0),
(9102, 'koKR', 'Dziękuję ci, śmiertelna istoto. Mogę oddać ci tylko jedną przysługę, nim wrócę do Snu.$B$BDrzwi do pana Zevrima, Alzzina, zagradzają ci drogę. Będę twoim narzędziem zniszczenia. Drzwi zostaną otwarte – czekam tylko na twój rozkaz.', '', 0),
(9104, 'koKR', 'Nareszcie... Uwolnienie z jego przeklętego uścisku!', '', 0),
(9220, 'koKR', 'Widzisz tamtą zepsutą pułapkę? Ogry są zbyt głupie, żeby wykombinować, jak ją naprawić. Najwyraźniej trzeba przy niej trochę pomajstrować! Jeśli ją naprawisz, założę się, że zwabisz w nią Slip\'kika i BUM – strażnik ogr w pułapce!', '', 0),
(9345, 'koKR', '$GZnalazłeś:Znalazłaś; klucz? No, ale czy to TEN klucz? Znaczy, czy to klucz do tych kajdan? Cóż, $gproszę pana:proszę pani;, jest tylko jeden sposób, żeby się przekonać!', '', 0),
(9346, 'koKR', '$n, dopilnuję, żeby wszyscy moi przyjaciele w Kartelu wiedzieli, że $guratowałeś:uratowałaś; mi dziś życie. Proszę – muszę podróżować z lekkim bagażem, więc częstuj się moim zapasem materiałów krawieckich i garbarskich! Jeszcze raz dzięki – na razie!', '', 0),
(9349, 'koKR', 'Jeśli chcesz klucz, musisz mnie złapać!', '', 0),
(9351, 'koKR', 'Klucz do wolności trzymam w dłoni! Goń mnie, a zobaczysz, kto kogo dogoni!', '', 0),
(9353, 'koKR', 'Goń mnie, jeśli się odważysz! Uciekam, a i tak nic mi nie zrobisz!', '', 0),
(9355, 'koKR', 'Ty mały...', 'Ty mały...', 0),
(9357, 'koKR', 'Czemu chcesz mnie skrzywdzić!? Chodź. Przyjaciółmi możemy być!', '', 0),
(9360, 'koKR', 'ZGINĄĆ?! Przez ciebie Pusillin płacze!', '', 0),
(9363, 'koKR', 'Przywitaj się z moimi małymi przyjaciółmi!', '', 0),
(9369, 'koKR', 'Cóż, z tego, co wywnioskowałem, czekając, aż zjedzą mnie te prostaki... może nie trzeba zabijać każdego ogra, którego tu spotkasz.$B$BOgry gadały kiedyś bez końca o tym, jak król Gordok doszedł do władzy – konkretnie zabił poprzedniego króla i zajął jego miejsce. No i poplecznicy króla – ci, których Gordok oszczędził – od razu przysięgli wierność nowemu królowi.$B$BKto wie – ogr, którego oszczędzisz, może równie dobrze okazać się twoim... oczywiście w przenośni!', '', 0),
(9371, 'koKR', 'Ty teraz szef, tak? Niech żyje nowy król!$B$BKreeg dać ci obejrzeć bimber Gordoków. Ogrzy bimber najlepszy ze wszystkich bimbrów, a bimber Gordoków najlepszy ze wszystkich ogrzych bimbrów! Może ty coś ode mnie kupić, co, szefie?!', '', 0),
(9379, 'koKR', '', 'Opuść to miejsce, nieznajomy, nim cię pochłonie, tak jak pochłonęło wszystko, czego dotknęło.', 0),
(9380, 'koKR', 'Co się tu stało, duchu?', 'Co się tu stało, duchu?', 0),
(9381, 'koKR', '', 'Czy wiesz coś o Wysoko Urodzonych? O Shen\'dralarach?', 0),
(9382, 'koKR', 'Niewiele wiem o Wysoko Urodzonych, a o Shen\'dralarach nic.', 'Niewiele wiem o Wysoko Urodzonych, a o Shen\'dralarach nic.', 0),
(9383, 'koKR', '', 'Shen\'dralarowie byli najbardziej poważanymi arkanistami królowej Aszary. To właśnie w tych murach załatwiano najważniejsze polecenia królowej – często w tajemnicy.$B$BPo zniszczeniu Studni i letargu, który potem ogarnął Wysoko Urodzonych i pomniejsze odłamy nocnych elfów, książę Eldre\'Thalas, Tortheldrin, zaczął budować pylony, które widzisz porozstawiane w korytarzach zachodniego skrzydła.\n', 0),
(9384, 'koKR', '', 'Książę uknuł plan, by uwięzić demona o ogromnej mocy za wielkim polem siłowym. Pylony miały kierować do pola uśpione energie i podtrzymywać jego działanie.$B$BUwięziony Immol\'thar miał służyć mieszkańcom Eldre\'Thalas jako źródło mocy.', 0),
(9386, 'koKR', 'Fascynujące. Mów dalej, proszę.', 'Fascynujące. Mów dalej, proszę.', 0),
(9387, 'koKR', '', 'Wysysana energia podtrzymywała magię Wysoko Urodzonych, pozwalając mieszkańcom Eldre\'Thalas zaspokajać ich nieskończony i wciąż rosnący głód magii.$B$BMinęły tysiące lat i moc potrzebna, by trzymać Immol\'thara w niewoli i zarazem podtrzymywać życie w Eldre\'Thalas, zaczęła się zmieniać. Koszt utrzymania Immol\'thara w okowach przerósł tempo, w jakim można było wysysać i rozdzielać energię. Dawny zysk zamienił się w stratę.', 0),
(9388, 'koKR', 'Pewnie przyjdzie mi coś zabić, prawda?', 'Pewnie przyjdzie mi coś zabić, prawda?', 0),
(9389, 'koKR', '', 'Duchy Wysoko Urodzonych, które widzisz wędrujące po dziedzińcu i korytarzach Eldre\'Thalas, nie zginęły z rąk najeźdźców – ogrów Gordoków ani satyrów – lecz z ręki samego księcia!', 0),
(9390, 'koKR', 'Żyjemy w świecie bezkresnych tragedii.', 'Żyjemy w świecie bezkresnych tragedii.', 0),
(9391, 'koKR', '', 'Lud wymordowano, by zachować nieśmiertelne życie księcia i jego niemal nieograniczoną moc. Moc, którą niegdyś dzieliły tysiące, teraz spływa do księcia i fanatyków Shen\'dralar. Nieliczni ocaleli zasilają pylony bezpośrednio, by utrzymać Immol\'thara w niewoli.$B$BGdyby demon zerwał więzy, z pewnością zniszczyłby to niewiele, co zostało z tego niegdyś wielkiego bastionu magii.', 0),
(9392, 'koKR', 'Bardzo smutna opowieść. Dziękuję ci, duchu.', 'Bardzo smutna opowieść. Dziękuję ci, duchu.', 0),
(9393, 'koKR', 'Teraz ty rządzić, ziom!', '', 0),
(9396, 'koKR', 'Fengus zrobić cię zajadłym! Obłąkanym! RAAR!', '', 0),
(9397, 'koKR', 'Ty mnie dobrze załatwić, szefie! Jak ty przejść obok Slip\'kika?? Ale ja mądry, następnym razem ja uważać! Har har!$B$BNikt już nie przejść obok Slip\'kika. Slip\'kik obiecać!', '', 0),
(9398, 'koKR', 'Jasne, prawdziwy z ciebie geniusz. Jak bardzo mądry myślisz, że jesteś, Slip\'kik?', 'Jasne, prawdziwy z ciebie geniusz. Jak bardzo mądry myślisz, że jesteś, Slip\'kik?', 0),
(9399, 'koKR', 'Ja ci pokazać, jak bardzo ja mądry, szefie! Ty teraz ekstra mądry z potężnym magicznym mojo!$B$BYyy... może Slip\'kik użyć magii na siebie. To być dobry pomysł...', '', 0),
(9400, 'koKR', 'Ty być król Gordoków! Ty numer jeden!', '', 0),
(9401, 'koKR', 'Mów mi „szefie”. Co tam dla mnie masz!', 'Mów mi „szefie”. Co tam dla mnie masz!', 0),
(9402, 'koKR', 'Słyszałem, że nie żyjesz... no, po tym niełatwo będzie cię uśmiercić!', '', 0),
(9403, 'koKR', 'Hej, Knot, jestem $ggarbarzem:garbarką;. Nauczysz mnie robić strój ogra?', 'Hej, Knot, jestem $ggarbarzem:garbarką;. Nauczysz mnie robić strój ogra?', 0),
(9404, 'koKR', 'Hej, Knot, jestem $gkrawcem:krawcową;. Nauczysz mnie robić strój ogra?', 'Hej, Knot, jestem $gkrawcem:krawcową;. Nauczysz mnie robić strój ogra?', 0),
(9406, 'koKR', 'Od 10 000 lat władam tym królestwem. W tym czasie słyszałem wiele fascynujących opowieści od tych, którzy stąpali po uświęconej ziemi Domu Shen\'dralar.$B$BPonieważ jestem związany z tym miejscem, często wymieniam się opowieściami z gośćmi. Masz dla mnie jakąś opowieść, a może chcesz jakąś usłyszeć?', '', 0),
(9407, 'koKR', 'Kto śmie zakłócać świętość Eldre\'Thalas? Stańcie do walki, tchórze!', '', 0),
(9408, 'koKR', 'Nie wolno nam rozgniewać Mistrza. Jego gniew jest okrutny ponad wszelką miarę.', 'Nie wolno nam rozgniewać Mistrza. Jego gniew jest okrutny ponad wszelką miarę.', 0),
(9409, 'koKR', 'Mów ciszej, nieznajomy. Nie chcesz przerwać medytacji Mistrza.', 'Mów ciszej, nieznajomy. Nie chcesz przerwać medytacji Mistrza.', 0),
(9410, 'koKR', 'Wielu przybyło do tego sanktuarium, niewielu je opuściło. ', 'Wielu przybyło do tego sanktuarium, niewielu je opuściło. ', 0),
(9412, 'koKR', 'Wiedzący jest pradawny. Służył jeszcze naszej wspaniałej królowej!', 'Wiedzący jest pradawny. Służył jeszcze naszej wspaniałej królowej!', 0),
(9416, 'koKR', 'Hej, kogo Fengus nazywać gnolofilem?! Zabrać więźniów do króla; ty mądry, że prowadzić ich z bronią i pokazać królowi, że oni zagrożenie. Ja iść sprawdzić, czy Fengus dalej gadać głupoty, jak ja mu spuścić łomot! HAR!', '', 0),
(9418, 'koKR', 'Nikt nie przejść obok mnie i nie grozić królowi! Ungh, masz!!', '', 0),
(9419, 'koKR', 'Co ty tu łazić? Czemu te małe płotki nie w kajdanach?!', '', 0),
(9420, 'koKR', 'Ty teraz silny! Chwała nowemu królowi Gordoków!', '', 0),
(9421, 'koKR', 'Eee, prowadzę przed oblicze króla kilku więźniów, których znaleźliśmy na zewnątrz. Na ukaranie.', 'Eee, prowadzę przed oblicze króla kilku więźniów, których znaleźliśmy na zewnątrz. Na ukaranie.', 0),
(9422, 'koKR', 'Czy ja widzieć, że oni dalej mieć broń? Czemu ty im zostawić broń?!', '', 0),
(9423, 'koKR', 'Eee... tak ich $gznalazłem:znalazłam;. $GChciałem:Chciałam; pokazać królowi, że są groźni! Słuchaj, kapitanie... $gpodsłuchałem:podsłuchałam;, jak strażnik Fengus nazywał cię tłustym, bezużytecznym gnolofilem!', 'Eee... tak ich $gznalazłem:znalazłam;. $GChciałem:Chciałam; pokazać królowi, że są groźni! Słuchaj, kapitanie... $gpodsłuchałem:podsłuchałam;, jak strażnik Fengus nazywał cię tłustym, bezużytecznym gnolofilem!', 0),
(9424, 'koKR', 'No, Fengus, gdzie ty być?! Ty przyjść nazwać mnie gnolofilem, jak ja ci przyłożyć młotem w łeb!', '', 0),
(9444, 'koKR', 'Yyy... ja przepraszać, że cię zaatakować, szefie. Ty mnie nie zabijać, proszę, dobra!? Ty teraz król, a ja pomóc zrobić twoją daninę lepszą!', '', 0),
(9445, 'koKR', 'Pobieżne oględziny szkieletu wskazują, że ciało zostało z niego zwęglone. Makabryczny widok.', '', 0),
(9446, 'koKR', 'Bardzo wątpię, by miał cokolwiek do powiedzenia, nieznajomy...', '', 0),
(9447, 'koKR', 'Mnie osobiście nie przeszkadzał. To książę nie tolerował wysokiego elfa w swojej domenie. Niestety nie mnie kwestionować decyzje księcia. Na jego obronę – nie spopielił mistrza Winthalusa od razu.', '', 0),
(9448, 'koKR', 'Z całą pewnością nie potrzebujemy, by ściągano na nas więcej uwagi, nieznajomy. Wróć do tych, którzy wysłali cię na poszukiwanie zaginionego mistrza, i powiedz im, że niczego nie znaleziono. Gdy to zrobisz – a będę wiedział, kiedy się to stanie – wróć, a wyjawię ci sekrety zmarłego.', '', 0),
(9449, 'koKR', 'Opłakuj wielką stratę.', 'Opłakuj wielką stratę.', 0),
(9451, 'koKR', 'No to skoro jestem królem... co tam dla mnie masz?!', 'No to skoro jestem królem... co tam dla mnie masz?!', 0),
(9455, 'koKR', 'Chwała nowemu królowi!', '', 0),
(9456, 'koKR', 'Jak ja się na ciebie krzywić, zanim ty zostać nowy król... yyy... ja tylko żartować.$B$BNo!', '', 0),
(9457, 'koKR', 'Te inne ogry głupie, że cię atakować, szefie! Dlatego ja dalej żyć – ja mądry i w ogóle!', '', 0),
(9458, 'koKR', 'My dużo czystsi niż ogry w Tanaris. Na całej pustyni, jak okiem sięgnąć – ogrza kupa. Nie tutaj, o nie, $gproszę pana:proszę pani;!', '', 0),
(9459, 'koKR', 'Dopóki ty zostać tu z nami, ty król. Ty odejść, to inny ogr zająć twoje miejsce. Taki być zwyczaj Gordoków!', '', 0),
(9460, 'koKR', 'Ja taki mondry! M-O-N-D-R-Y!', '', 0),
(9461, 'koKR', 'Stary król nie żyć? To niemożebne!', '', 0),
(9462, 'koKR', 'Ja nie robić ci kłopotów, szefie.', '', 0),
(9463, 'koKR', 'Ojej, gdzie jest „Kodeks obrony”? Lydros będzie z pewnością bardzo niezadowolony.', '', 0),
(9465, 'koKR', '„Książki kucharskiej arkanisty” też nie ma! To katastrofa!', '', 0),
(9466, 'koKR', 'Ostatnio znikają księgi. Wiedzący i jego pomocnicy są w szale. Podejrzewają, że w Eldre\'Thalas ktoś knuje.', 'Ostatnio znikają księgi. Wiedzący i jego pomocnicy są w szale. Podejrzewają, że w Eldre\'Thalas ktoś knuje.', 0),
(9467, 'koKR', 'Czy książę opowiedział ci już historię Spopielacza? To nasza ulubiona z jego opowieści. Jego ulubioną jest dalszy ciąg historii Spopielacza. Oczywiście nikomu jeszcze nie udało się jej z niego wyciągnąć.', 'Czy książę opowiedział ci już historię Spopielacza? To nasza ulubiona z jego opowieści. Jego ulubioną jest dalszy ciąg historii Spopielacza. Oczywiście nikomu jeszcze nie udało się jej z niego wyciągnąć.', 0),
(9468, 'koKR', 'Podejrzewam, że to chochliki kradną wiedzę.', 'Podejrzewam, że to chochliki kradną wiedzę.', 0),
(9469, 'koKR', 'Mistrz bardzo interesuje się leżem Nefariana. Gdyby tylko ktoś pokonał smoka i jego sługi, a potem opowiedział o tym księciu. Założę się, że to rozwiązałoby księciu język. Spopielacz mógłby się odnaleźć!', 'Mistrz bardzo interesuje się leżem Nefariana. Gdyby tylko ktoś pokonał smoka i jego sługi, a potem opowiedział o tym księciu. Założę się, że to rozwiązałoby księciu język. Spopielacz mógłby się odnaleźć!', 0),
(9470, 'koKR', 'Jak ty nie gadać z Mizzle\'em, ty nie zostać król! Gadaj z Mizzle\'em Przebiegłym!', '', 0),
(9473, 'koKR', 'Musisz zrozumieć, że możliwość skatalogowania 10 000 lat istnienia dała mi dość wyjątkowe spojrzenie na życie. Twoje dzisiejsze próby i utrapienia nie mają żadnego znaczenia.', '', 0),
(9475, 'koKR', 'Gdzie jest „Garona: studium skrytości i zdrady”! Te teksty muszą wrócić na miejsce! ', '', 0),
(9476, 'koKR', 'Zostały skradzione! Trzy z naszych najcenniejszych tomów. Jeśli je zwrócisz, nagroda z pewnością cię nie ominie.', '', 0),
(9477, 'koKR', '%s zaczyna oddawać każdy cios!', '', 0),
(9478, 'koKR', 'Pomóc mi zmiażdżyć te chuchra!', '', 0),
(9481, 'koKR', 'Wy mi nie rzucać wyzwania, cieniasy! Ja teraz król i ja zostać królem NA ZAWSZE!!!', '', 0),
(9482, 'koKR', 'Oj!', '', 0),
(9489, 'koKR', '%s wyczuwa twoją obecność i otwiera portal Otchłani!', '', 0),
(9509, 'koKR', 'Dziesięć tysięcy lat spisanej wiedzy zwykle przyciąga do Atenaeum niewłaściwy element. Księgi są kradzione, odzyskiwane i znów kradzione dzień w dzień.', '', 0),
(9510, 'koKR', '', 'Kildrath ma skłonność do dramatyzowania. Na przykład „Garonę: studium skrytości i zdrady” skradziono już ponad 400 razy.$B$BZnak Atenaeum chroni tomy przed czytaniem przez niepowołanych.', 0),
(11727, 'koKR', 'Nie macie tu czego szukać! Pradawni, powstańcie przeciw tym intruzom!', '', 0);
